/**
 * Alternative 100-camera-per-city year-round arrangements for benchmarking against the
 * Prominent Hotspot Scatter plan, plus a 3-year (2024–2026) synthetic animal crossing dataset.
 * All camera placements and sightlines are snapped directly to official Finnish Digiroad motor roads.
 */

export type HotspotClusterTuple = [
  lat: number,
  lng: number,
  bearingDeg: number,
  clusterIndex: number,
  roadLabel: string,
];

export type WideCorridorCameraTuple = [
  lat: number,
  lng: number,
  bearingDeg: number,
  rankInCity: number,
  historicalAccidents: number,
  roadLabel: string,
];

export type SyntheticCrossingTuple = [
  eventId: string,
  date: string,
  lat: number,
  lng: number,
  animalSize: 'large' | 'small',
];

